inputs = ['gkc', 'jzhvw', 'ehbwb', 'fbf', 'bvag']
outputs = ['gkc', 'jjvvhx', 'kzgzghbwb', 'fbf', 'bvag']

print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\n{i+1}. '{inp}' -> '{out}'")
    print(f"   Length: {len(inp)} -> {len(out)}")

    # Show character by character
    min_len = min(len(inp), len(out))
    for j in range(max(len(inp), len(out))):
        in_char = inp[j] if j < len(inp) else "(none)"
        out_char = out[j] if j < len(out) else "(none)"
        if in_char != out_char:
            print(f"   Position {j}: '{in_char}' -> '{out_char}'")

    if len(inp) != len(out):
        if len(inp) > len(out):
            print(f"   Extra chars removed: '{inp[len(out):]}'")
        else:
            print(f"   Extra chars added: '{out[len(inp):]}'")

print("\nLooking for consistent patterns...")
# Let me check if there's a pattern in the differences
print("Checking for common transformations...")
transformations = {}
for inp, out in zip(inputs, outputs):
    if inp != out:
        # Try to find what characters change
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                if (inp[j], out[j]) not in transformations:
                    transformations[(inp[j], out[j])] = 0
                transformations[(inp[j], out[j])] += 1

print("Character transformations found:", transformations)

